package linkedlist

// node is a single element of the singly-linked list.
type node struct {
	value int64
	next  *node
}

// List is a simple singly-linked FIFO list of int64 values.
type List struct {
	head *node
	tail *node
	size int
}

// New creates an empty list.
func New() *List {
	return &List{}
}

// PushBack appends a value to the end of the list.
func (l *List) PushBack(v int64) {
	n := &node{value: v}
	if l.tail == nil {
		l.head = n
		l.tail = n
	} else {
		l.tail.next = n
		l.tail = n
	}
	l.size++
}

// PushFront prepends a value to the start of the list.
func (l *List) PushFront(v int64) {
	n := &node{value: v, next: l.head}
	l.head = n
	if l.tail == nil {
		l.tail = n
	}
	l.size++
}

// PopFront removes and returns the value at the front of the list.
func (l *List) PopFront() int64 {
	if l.head == nil {
		panic("linkedlist: pop from empty list")
	}
	v := l.head.value
	l.head = l.head.next
	if l.head == nil {
		l.tail = nil
	}
	l.size--
	return v
}

// Front returns the value at the front without removing it.
func (l *List) Front() int64 {
	if l.head == nil {
		panic("linkedlist: front of empty list")
	}
	return l.head.value
}

// Len returns the number of elements in the list.
func (l *List) Len() int {
	return l.size
}

// IsEmpty reports whether the list has no elements.
func (l *List) IsEmpty() bool {
	return l.size == 0
}

// ToSlice returns a snapshot of all elements from front to back.
func (l *List) ToSlice() []int64 {
	out := make([]int64, 0, l.size)
	cur := l.head
	for cur != nil {
		out = append(out, cur.value)
		cur = cur.next
	}
	return out
}

// Contains reports whether v exists anywhere in the list.
func (l *List) Contains(v int64) bool {
	cur := l.head
	for cur != nil {
		if cur.value == v {
			return true
		}
		cur = cur.next
	}
	return false
}

// RemoveFirst removes the first occurrence of v, if present. Returns true if removed.
func (l *List) RemoveFirst(v int64) bool {
	if l.head == nil {
		return false
	}
	if l.head.value == v {
		l.PopFront()
		return true
	}
	prev := l.head
	cur := l.head.next
	for cur != nil {
		if cur.value == v {
			prev.next = cur.next
			if cur == l.tail {
				l.tail = prev
			}
			l.size--
			return true
		}
		prev = cur
		cur = cur.next
	}
	return false
}

package pricefeed

// Observation is a single price sample at a given block height.
type Observation struct {
	Height int64
	Price  int64 // fixed-point-agnostic raw price, caller defines scale
}

// WeightedAverage computes a simple time-weighted average price (TWAP-style)
// across a series of observations. Weight of each observation is the number
// of blocks it was in effect for (until the next observation, or until
// `uptoHeight` for the last one). Observations must be sorted ascending by Height.
func WeightedAverage(obs []Observation, uptoHeight int64) int64 {
	if len(obs) == 0 {
		panic("pricefeed: no observations")
	}
	if len(obs) == 1 {
		return obs[0].Price
	}

	var weightedSum int64
	var totalWeight int64
	for i := 0; i < len(obs); i++ {
		var weight int64
		if i+1 < len(obs) {
			weight = obs[i+1].Height - obs[i].Height
		} else {
			weight = uptoHeight - obs[i].Height
		}
		if weight < 0 {
			panic("pricefeed: observations must be sorted ascending and uptoHeight must not precede last observation")
		}
		weightedSum += obs[i].Price * weight
		totalWeight += weight
	}
	if totalWeight == 0 {
		return obs[len(obs)-1].Price
	}
	return weightedSum / totalWeight
}

// WithinSlippage reports whether actualPrice is within toleranceBps (basis
// points, 1/100 of a percent) of referencePrice.
func WithinSlippage(referencePrice int64, actualPrice int64, toleranceBps int64) bool {
	if referencePrice <= 0 {
		panic("pricefeed: referencePrice must be positive")
	}
	if toleranceBps < 0 {
		panic("pricefeed: toleranceBps must be non-negative")
	}
	diff := actualPrice - referencePrice
	if diff < 0 {
		diff = -diff
	}
	// diff / referencePrice <= toleranceBps / 10000
	return diff*10000 <= referencePrice*toleranceBps
}

// ApplySlippage returns the minimum acceptable output amount given an
// expected amount and a tolerance in basis points.
func ApplySlippage(expectedAmount int64, toleranceBps int64) int64 {
	if expectedAmount < 0 {
		panic("pricefeed: expectedAmount must be non-negative")
	}
	if toleranceBps < 0 || toleranceBps > 10000 {
		panic("pricefeed: toleranceBps must be between 0 and 10000")
	}
	return expectedAmount * (10000 - toleranceBps) / 10000
}

package stringutils

// Contains reports whether substr is within s.
func Contains(s string, substr string) bool {
	return IndexOf(s, substr) >= 0
}

// IndexOf returns the index of the first occurrence of substr in s, or -1.
func IndexOf(s string, substr string) int {
	n := len(s)
	m := len(substr)
	if m == 0 {
		return 0
	}
	if m > n {
		return -1
	}
	for i := 0; i <= n-m; i++ {
		match := true
		for j := 0; j < m; j++ {
			if s[i+j] != substr[j] {
				match = false
				break
			}
		}
		if match {
			return i
		}
	}
	return -1
}

// Split divides s by every occurrence of sep, returning the resulting parts.
// If sep is empty, returns a slice with s as its only element.
func Split(s string, sep string) []string {
	if sep == "" {
		return []string{s}
	}
	parts := []string{}
	start := 0
	sepLen := len(sep)
	for {
		idx := IndexOf(s[start:], sep)
		if idx < 0 {
			parts = append(parts, s[start:])
			break
		}
		parts = append(parts, s[start:start+idx])
		start = start + idx + sepLen
	}
	return parts
}

// TrimSpace removes leading and trailing ASCII whitespace from s.
func TrimSpace(s string) string {
	start := 0
	end := len(s)
	for start < end && isSpace(s[start]) {
		start++
	}
	for end > start && isSpace(s[end-1]) {
		end--
	}
	return s[start:end]
}

func isSpace(b byte) bool {
	return b == ' ' || b == '\t' || b == '\n' || b == '\r'
}

// HasPrefix reports whether s begins with prefix.
func HasPrefix(s string, prefix string) bool {
	if len(prefix) > len(s) {
		return false
	}
	return s[:len(prefix)] == prefix
}

// HasSuffix reports whether s ends with suffix.
func HasSuffix(s string, suffix string) bool {
	if len(suffix) > len(s) {
		return false
	}
	return s[len(s)-len(suffix):] == suffix
}

// Join concatenates parts, separating each with sep.
func Join(parts []string, sep string) string {
	if len(parts) == 0 {
		return ""
	}
	out := parts[0]
	for i := 1; i < len(parts); i++ {
		out += sep + parts[i]
	}
	return out
}

// Repeat returns s concatenated count times.
func Repeat(s string, count int) string {
	if count <= 0 {
		return ""
	}
	out := ""
	for i := 0; i < count; i++ {
		out += s
	}
	return out
}

// ToUpper converts ASCII lowercase letters in s to uppercase.
func ToUpper(s string) string {
	buf := []byte(s)
	for i, b := range buf {
		if b >= 'a' && b <= 'z' {
			buf[i] = b - 32
		}
	}
	return string(buf)
}

// ToLower converts ASCII uppercase letters in s to lowercase.
func ToLower(s string) string {
	buf := []byte(s)
	for i, b := range buf {
		if b >= 'A' && b <= 'Z' {
			buf[i] = b + 32
		}
	}
	return string(buf)
}

package timelock

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Status represents the lifecycle of a timelocked transfer.
type Status int

const (
	StatusPending Status = iota
	StatusExecuted
	StatusCancelled
)

func (s Status) String() string {
	switch s {
	case StatusPending:
		return "pending"
	case StatusExecuted:
		return "executed"
	case StatusCancelled:
		return "cancelled"
	default:
		return "unknown"
	}
}

// LockedTransfer is a ugnot transfer that can only be executed once
// the chain reaches ExecutableAt, giving observers a window to react.
type LockedTransfer struct {
	ID            int64
	Creator       address
	Recipient     address
	Amount        int64
	ExecutableAt  int64
	Status        Status
}

const minDelayBlocks int64 = 10

var (
	transfers *avl.Tree // id (string) -> *LockedTransfer
	nextID    int64
)

func init() {
	transfers = avl.NewTree()
	nextID = 1
}

func assertUserCall(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("timelock: must be a direct user call")
	}
	return cur.Previous().Address()
}

func idKey(id int64) string {
	return ufmt.Sprintf("%020d", id)
}

func getTransfer(id int64) *LockedTransfer {
	key := idKey(id)
	if !transfers.Has(key) {
		panic("timelock: transfer not found")
	}
	raw := transfers.Get(key)
	return raw.(*LockedTransfer)
}

// Schedule queues a ugnot transfer, funded now, executable after delayBlocks.
func Schedule(cur realm, recipient address, delayBlocks int64) int64 {
	caller := assertUserCall(cur)
	if delayBlocks < minDelayBlocks {
		panic("timelock: delayBlocks below minimum")
	}
	sent := unsafe.OriginSend()
	amount := sent.AmountOf("ugnot")
	if amount <= 0 {
		panic("timelock: must fund the transfer with ugnot")
	}

	id := nextID
	nextID++

	transfers.Set(idKey(id), &LockedTransfer{
		ID:           id,
		Creator:      caller,
		Recipient:    recipient,
		Amount:       amount,
		ExecutableAt: runtime.ChainHeight() + delayBlocks,
		Status:       StatusPending,
	})
	return id
}

// Execute releases the funds to the recipient once the delay has elapsed.
// Callable by anyone, so execution isn't dependent on the creator being online.
func Execute(cur realm, id int64) {
	assertUserCall(cur)
	t := getTransfer(id)
	if t.Status != StatusPending {
		panic("timelock: transfer is not pending")
	}
	if runtime.ChainHeight() < t.ExecutableAt {
		panic("timelock: delay has not elapsed yet")
	}

	realmAddr := cur.Address()
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	have := bk.GetCoins(realmAddr).AmountOf("ugnot")
	amount := t.Amount
	if amount > have {
		amount = have
	}
	if amount > 0 {
		bk.SendCoins(realmAddr, t.Recipient, chain.Coins{chain.NewCoin("ugnot", amount)})
	}

	t.Status = StatusExecuted
}

// Cancel lets the creator abort a pending transfer and reclaim funds,
// as long as it hasn't become executable yet.
func Cancel(cur realm, id int64) {
	caller := assertUserCall(cur)
	t := getTransfer(id)
	if t.Status != StatusPending {
		panic("timelock: transfer is not pending")
	}
	if caller != t.Creator {
		panic("timelock: only the creator can cancel")
	}
	if runtime.ChainHeight() >= t.ExecutableAt {
		panic("timelock: cannot cancel after executable window opens")
	}

	realmAddr := cur.Address()
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	have := bk.GetCoins(realmAddr).AmountOf("ugnot")
	amount := t.Amount
	if amount > have {
		amount = have
	}
	if amount > 0 {
		bk.SendCoins(realmAddr, t.Creator, chain.Coins{chain.NewCoin("ugnot", amount)})
	}

	t.Status = StatusCancelled
}

func Render(path string) string {
	out := "# Timelock\n\n"
	out += ufmt.Sprintf("Total scheduled transfers: %d\n\n", transfers.Size())
	transfers.Iterate("", "", func(key string, value interface{}) bool {
		t := value.(*LockedTransfer)
		out += ufmt.Sprintf("## #%d\n", t.ID)
		out += ufmt.Sprintf("Recipient: %s | Amount: %d ugnot | Executable at: %d | Status: %s\n\n",
			t.Recipient, t.Amount, t.ExecutableAt, t.Status.String())
		return false
	})
	return out
}

package splitpayment

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Payee is a recipient with a share expressed in basis points (1/100 of a percent).
type Payee struct {
	Addr    address
	ShareBp int64 // basis points, all payees must sum to 10000
}

// Splitter is a payment group: any funds sent to Distribute are divided
// among the configured payees according to their shares.
type Splitter struct {
	ID       int64
	Owner    address
	Payees   []Payee
	TotalIn  int64
	TotalOut *avl.Tree // addr -> int64, cumulative amount paid to each payee
}

var (
	splitters *avl.Tree // id (string) -> *Splitter
	nextID    int64
)

func init() {
	splitters = avl.NewTree()
	nextID = 1
}

func assertUserCall(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("splitpayment: must be a direct user call")
	}
	return cur.Previous().Address()
}

func idKey(id int64) string {
	return ufmt.Sprintf("%020d", id)
}

func getSplitter(id int64) *Splitter {
	key := idKey(id)
	if !splitters.Has(key) {
		panic("splitpayment: splitter not found")
	}
	raw := splitters.Get(key)
	return raw.(*Splitter)
}

// CreateSplitter defines a new payee group. Shares (in basis points) must sum to 10000.
func CreateSplitter(cur realm, addr0 address, bp0 int64, addr1 address, bp1 int64, addr2 address, bp2 int64, addr3 address, bp3 int64) int64 {
	caller := assertUserCall(cur)

	payees := []Payee{}
	candidates := []Payee{
		{Addr: addr0, ShareBp: bp0},
		{Addr: addr1, ShareBp: bp1},
		{Addr: addr2, ShareBp: bp2},
		{Addr: addr3, ShareBp: bp3},
	}
	var total int64
	for _, p := range candidates {
		if p.Addr != address("") && p.ShareBp > 0 {
			payees = append(payees, p)
			total += p.ShareBp
		}
	}
	if len(payees) < 2 {
		panic("splitpayment: at least 2 payees required")
	}
	if total != 10000 {
		panic("splitpayment: shares must sum to exactly 10000 basis points")
	}

	id := nextID
	nextID++

	splitters.Set(idKey(id), &Splitter{
		ID:       id,
		Owner:    caller,
		Payees:   payees,
		TotalOut: avl.NewTree(),
	})
	return id
}

// Distribute accepts a ugnot payment and immediately splits it among payees
// proportional to their configured shares. Remainder from integer division
// goes to the first payee.
func Distribute(cur realm, id int64) {
	assertUserCall(cur)
	s := getSplitter(id)

	sent := unsafe.OriginSend()
	amount := sent.AmountOf("ugnot")
	if amount <= 0 {
		panic("splitpayment: must send ugnot to distribute")
	}
	s.TotalIn += amount

	realmAddr := cur.Address()
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)

	var distributed int64
	for i, p := range s.Payees {
		var share int64
		if i == len(s.Payees)-1 {
			share = amount - distributed // give remainder to last payee
		} else {
			share = amount * p.ShareBp / 10000
			distributed += share
		}
		if share > 0 {
			bk.SendCoins(realmAddr, p.Addr, chain.Coins{chain.NewCoin("ugnot", share)})
			key := string(p.Addr)
			existing := int64(0)
			if s.TotalOut.Has(key) {
				existing = s.TotalOut.Get(key).(int64)
			}
			s.TotalOut.Set(key, existing+share)
		}
	}
}

func Render(path string) string {
	out := "# Split Payment\n\n"
	out += ufmt.Sprintf("Total splitters: %d\n\n", splitters.Size())
	splitters.Iterate("", "", func(key string, value interface{}) bool {
		s := value.(*Splitter)
		out += ufmt.Sprintf("## #%d | Total in: %d ugnot\n", s.ID, s.TotalIn)
		for _, p := range s.Payees {
			out += ufmt.Sprintf("- %s: %d bp\n", p.Addr, p.ShareBp)
		}
		out += "\n"
		return false
	})
	return out
}

package whitelist

import (
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"

	"gno.land/p/g16m0r7rm7fv5hx0ekr7gvx8g4fr7eu08nzhk6gt/ratelimit"
)

// Entry records when an address was whitelisted and by whom.
type Entry struct {
	Addr       address
	AddedBy    address
	AddedAt    int64
}

var (
	admin        address
	entries      *avl.Tree // addr -> *Entry
	selfRequests *avl.Tree // addr -> *ratelimit.TokenBucket, throttles self-service requests
	openEnrollment bool
)

func init() {
	admin = address("g16m0r7rm7fv5hx0ekr7gvx8g4fr7eu08nzhk6gt")
	entries = avl.NewTree()
	selfRequests = avl.NewTree()
	openEnrollment = false
}

func assertUserCall(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("whitelist: must be a direct user call")
	}
	return cur.Previous().Address()
}

// AddAddress lets the admin add an address directly.
func AddAddress(cur realm, addr address) {
	caller := assertUserCall(cur)
	if caller != admin {
		panic("whitelist: admin only")
	}
	entries.Set(string(addr), &Entry{
		Addr:    addr,
		AddedBy: caller,
		AddedAt: runtime.ChainHeight(),
	})
}

// RemoveAddress lets the admin revoke an address.
func RemoveAddress(cur realm, addr address) {
	caller := assertUserCall(cur)
	if caller != admin {
		panic("whitelist: admin only")
	}
	key := string(addr)
	if entries.Has(key) {
		entries.Remove(key)
	}
}

// SetOpenEnrollment toggles whether addresses can self-enroll via RequestJoin.
func SetOpenEnrollment(cur realm, open bool) {
	caller := assertUserCall(cur)
	if caller != admin {
		panic("whitelist: admin only")
	}
	openEnrollment = open
}

// RequestJoin lets any address self-enroll when open enrollment is active,
// rate-limited to prevent spam.
func RequestJoin(cur realm) {
	caller := assertUserCall(cur)
	if !openEnrollment {
		panic("whitelist: open enrollment is not active")
	}
	key := string(caller)
	if entries.Has(key) {
		panic("whitelist: already whitelisted")
	}

	now := runtime.ChainHeight()
	var bucket *ratelimit.TokenBucket
	if selfRequests.Has(key) {
		bucket = selfRequests.Get(key).(*ratelimit.TokenBucket)
	} else {
		bucket = ratelimit.NewTokenBucket(3, 1, now)
		selfRequests.Set(key, bucket)
	}
	if !bucket.Allow(now, 1) {
		panic("whitelist: rate limit exceeded, try again later")
	}

	entries.Set(key, &Entry{
		Addr:    caller,
		AddedBy: caller,
		AddedAt: now,
	})
}

// IsWhitelisted reports whether an address is currently on the list.
func IsWhitelisted(addr address) bool {
	return entries.Has(string(addr))
}

func Render(path string) string {
	out := "# Whitelist\n\n"
	status := "closed"
	if openEnrollment {
		status = "open"
	}
	out += ufmt.Sprintf("Enrollment: %s | Total entries: %d\n\n", status, entries.Size())
	entries.Iterate("", "", func(key string, value interface{}) bool {
		e := value.(*Entry)
		out += ufmt.Sprintf("- %s (added by %s at height %d)\n", e.Addr, e.AddedBy, e.AddedAt)
		return false
	})
	return out
}
